import React, { useContext } from "react";
import {
  HashRouter,
  Routes,
  Route
} from "react-router-dom";

import RootLayout from './Components/layout/RootLayout';
import ProductList from './Components/product/ProductList';
import Cart from './Components/product/Cart';
import Home from './Components/pages/Home';
import Login from './Components/pages/Login';
import Signup from './Components/pages/SignUp';
import Logout from './Components/pages/LogOut';
import ProductCategorySearch from './Components/product/ProductCategorySearch';
import ProductDetail from './Components/product/ProductDetail';
import NotFound from './Components/pages/NotFound';
import Welcome from './Components/pages/Welcome';

import { CartProvider } from './context/cartContext';
import { AuthProvider, AuthContext } from './context/authContext';

const AppRoutes = () => {
  const { user } = useContext(AuthContext);

  return (
    <HashRouter>
      <RootLayout>
        <Routes>
          <Route path="/" element={<Welcome />} />
          <Route path="/login" element={!user ? <Login /> : <Home />} />
          <Route path="/signup" element={!user ? <Signup /> : <Home />} />
          <Route path="/home" element={user ? <Home /> : <Login />} />
          <Route path="/products" element={user ? <ProductList /> : <Login />} />
          <Route path="/cart" element={user ? <Cart /> : <Login />} />
          <Route path="/logout" element={!user ? <Login /> : <Logout />} />
          <Route path="/category/:category" element={user ? <ProductCategorySearch /> : <Login />} />
          <Route path="/productdetails/:id" element={user ? <ProductDetail /> : <Login />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </RootLayout>
    </HashRouter>
  );
};

function App() {
  return (
    <AuthProvider>
      <CartProvider>
        <AppRoutes />
      </CartProvider>
    </AuthProvider>
  );
}

export default App;
